const esc = (value="") => String(value).replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[char]);
const norm = value => String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
function publicAsset(value){return String(value||"").replace(/^media\//,"");}
function productImages(product){const list=Array.isArray(product.images)?product.images.map(item=>publicAsset(typeof item==="string"?item:item?.url)).filter(Boolean):[];return list.length?list:[publicAsset(product.image)||"producto-1.jpg"];}
function productPaths(product){const list=Array.isArray(product.storagePaths)?product.storagePaths.filter(Boolean):[];return list.length?list:(product.storagePath?[product.storagePath]:[]);}
function normalizeProduct(product){return {...product,id:String(product.id||""),category:LEGACY_CATEGORIES[product.category]||product.category||"camisetas",sizes:Array.isArray(product.sizes)?product.sizes:[],images:productImages(product),storagePaths:productPaths(product),image:productImages(product)[0],active:product.active!==false,condition:String(product.condition||"Muy buen estado"),color:String(product.color||""),material:String(product.material||""),measurements:String(product.measurements||""),authenticity:String(product.authenticity||""),unique:product.unique!==false,stock:typeof product.stock==="number"?product.stock:0};}
function productSignature(products){return JSON.stringify(products.map(product=>[product.id,product.name,product.brand,product.category,product.price,product.image,product.badge,product.sizes,product.active,product.createdOrder,product.condition,product.color,product.material,product.measurements,product.authenticity,product.unique]));}
function readProductCache(){try{const parsed=JSON.parse(sessionStorage.getItem(PRODUCT_CACHE_KEY)||"null");return Array.isArray(parsed)?parsed.map(normalizeProduct):null;}catch{return null;}}
function writeProductCache(products){try{sessionStorage.setItem(PRODUCT_CACHE_KEY,JSON.stringify(products));}catch{/* El gestor continúa sin caché. */}}
function price(value){const raw=String(value??"").trim();if(!raw||norm(raw)==="consultar")return"Consultar";const number=Number(raw.replace(/\./g,"").replace(",","."));return Number.isFinite(number)?new Intl.NumberFormat("es-ES",{style:"currency",currency:"EUR"}).format(number):raw;}
function initials(brand){return brand.split(/[\s&()-]+/).filter(Boolean).slice(0,2).map(part=>part[0]).join("").toUpperCase();}
function validProductPrice(value){const raw=String(value??"").trim();if(!raw||norm(raw)==="consultar")return true;const cleaned=raw.replace(/[^\d.,-]/g,"");if(!cleaned)return false;const normalized=cleaned.includes(",")?cleaned.replace(/\./g,"").replace(",", "."):cleaned;const number=Number(normalized);return Number.isFinite(number)&&number>=0;}
function firestoreAdminMessage(error,fallback="No se ha podido guardar el cambio."){const code=String(error?.code||"").toLowerCase(),message=String(error?.message||"").toLowerCase();if(code.includes("permission-denied")||message.includes("permission"))return"Firebase ha bloqueado el cambio. Publica el archivo firestore.rules incluido con la web y vuelve a iniciar sesión.";if(code.includes("unavailable")||message.includes("offline")||message.includes("network"))return"No hay conexión con Firebase. Comprueba Internet e inténtalo de nuevo.";return fallback;}

function setActiveNav(view){document.querySelectorAll("[data-admin-view]").forEach(button=>button.classList.toggle("active",button.dataset.adminView===view));document.body.classList.remove("admin-menu-open");}
function goTo(view,id=""){
  if(state.dirty&&state.view==="editor"&&view!=="editor"&&!confirm("Tienes cambios sin guardar. ¿Quieres salir del editor?"))return;
  state.view=view;state.editId=id;state.dirty=false;setActiveNav(view);render();root.focus();
}
function render(){if(!state.ready)return;if(state.role!=="admin"){renderDenied();return;}if(state.view==="editor")renderEditor();else if(state.view==="stock")renderStock();else if(state.view==="jerseyExamples")renderJerseyExamples();else if(state.view==="profile")renderProfile();else if(state.view==="requests")renderRequests();else if(!state.productsReady)renderCatalogLoading();else renderCatalog();updatePendingRequestCount();}

function renderCatalogLoading(){root.innerHTML=`<div class="admin-main-shell"><header class="admin-page-head"><div><p class="kicker">GESTIÓN DE CATÁLOGO</p><h1>Mis artículos</h1><span>Sincronizando el catálogo…</span></div></header><div class="admin-loading-list" aria-label="Cargando catálogo">${Array.from({length:5},()=>'<div><i></i><span></span><b></b></div>').join("")}</div></div>`;}

