function filteredProducts(){const term=norm(state.search);return state.products.filter(product=>{const match=!term||norm([product.name,product.brand,CATEGORY_LABELS[product.category],product.description].join(" ")).includes(term);return match&&(state.category==="all"||product.category===state.category)&&(state.status==="all"||(state.status==="published"?product.active:!product.active));});}
function renderCatalog(){
  const products=filteredProducts();
  root.innerHTML=`<div class="admin-main-shell"><header class="admin-page-head"><div><p class="kicker">GESTIÓN DE CATÁLOGO</p><h1>Mis artículos</h1><span>${state.products.length} artículo${state.products.length===1?"":"s"} en el catálogo</span></div><div class="admin-head-actions"><a class="admin-secondary-link" href="catalogo.html" target="_blank" rel="noopener">Ver tienda ↗</a><button class="button button-primary" id="newProduct" type="button">＋ Nuevo artículo</button></div></header>
    <div class="admin-toolbar"><label class="admin-search"><span>⌕</span><input id="adminSearch" type="search" value="${esc(state.search)}" placeholder="Buscar artículos, marcas o categorías"></label><select id="adminCategory"><option value="all">Todas las categorías</option>${CATEGORIES.map(item=>`<option value="${item[0]}" ${state.category===item[0]?"selected":""}>${esc(item[1])}</option>`).join("")}</select><select id="adminStatus"><option value="all">Todos los estados</option><option value="published" ${state.status==="published"?"selected":""}>Publicados</option><option value="draft" ${state.status==="draft"?"selected":""}>Borradores</option></select></div>
    ${products.length?`<div class="admin-product-list">${products.map(productRow).join("")}</div>`:`<div class="admin-empty"><span>◇</span><h2>${state.products.length?"No hay coincidencias":"Tu catálogo está preparado"}</h2><p>${state.products.length?"Prueba con otra búsqueda o cambia los filtros.":"Añade el primer artículo para empezar."}</p><button class="button button-primary" id="emptyNewProduct" type="button">＋ Nuevo artículo</button></div>`}</div>`;
  bindCatalog();
}
function productRow(product){return `<article class="admin-product-row"><img src="${esc(product.image)}" alt="${esc(product.name)}" onerror="this.src='producto-1.jpg'"><div><h3>${esc(product.name)}</h3><p>${esc(product.brand||"GinesCloset")}</p></div><small>${esc(CATEGORY_LABELS[product.category]||product.category)}</small><small>${product.sizes.length?esc(product.sizes.join(", ")):"Talla única"}</small><strong>${esc(price(product.price))}</strong><span class="status-pill ${product.active?"published":"draft"}">${product.active?"Publicado":"Borrador"}</span><div class="row-actions"><button data-edit="${esc(product.id)}" type="button">Editar</button><div class="more-menu"><button data-more="${esc(product.id)}" type="button" aria-label="Más acciones">•••</button><div class="more-popover hidden" data-menu="${esc(product.id)}"><button data-duplicate="${esc(product.id)}" type="button">Duplicar</button><button class="danger" data-delete="${esc(product.id)}" type="button">Eliminar</button></div></div></div></article>`;}
function bindCatalog(){
  root.querySelector("#newProduct")?.addEventListener("click",()=>goTo("editor"));root.querySelector("#emptyNewProduct")?.addEventListener("click",()=>goTo("editor"));
  root.querySelector("#adminSearch")?.addEventListener("input",event=>{state.search=event.target.value;clearTimeout(renderCatalog.timer);renderCatalog.timer=setTimeout(()=>{renderCatalog();const next=root.querySelector("#adminSearch");next?.focus();next?.setSelectionRange(next.value.length,next.value.length);},140);});
  root.querySelector("#adminCategory")?.addEventListener("change",event=>{state.category=event.target.value;renderCatalog();});root.querySelector("#adminStatus")?.addEventListener("change",event=>{state.status=event.target.value;renderCatalog();});
  root.querySelectorAll("[data-edit]").forEach(button=>button.addEventListener("click",()=>goTo("editor",button.dataset.edit)));
  root.querySelectorAll("[data-more]").forEach(button=>button.addEventListener("click",event=>{event.stopPropagation();const menu=root.querySelector(`[data-menu="${CSS.escape(button.dataset.more)}"]`);root.querySelectorAll(".more-popover").forEach(item=>{if(item!==menu)item.classList.add("hidden")});menu.classList.toggle("hidden");}));
  root.querySelectorAll("[data-duplicate]").forEach(button=>button.addEventListener("click",()=>duplicateProduct(button.dataset.duplicate)));
  root.querySelectorAll("[data-delete]").forEach(button=>button.addEventListener("click",()=>confirmDelete(button.dataset.delete)));
}

