function exampleCard(example){return `<article class="admin-example-card"><img src="${esc(example.image||"producto-1.jpg")}" alt="${esc(example.name||"Ejemplo")}" onerror="this.src='producto-1.jpg'"><div><b>${esc(example.name||"Ejemplo")}</b><button class="button button-danger-outline" data-delete-example="${esc(example.id)}" type="button">Eliminar</button></div></article>`;}
function bindJerseyExamples(){
  const form=root.querySelector("#jerseyExampleForm");if(!form)return;
  const input=form.querySelector("#exampleInput"),cameraInput=form.querySelector("#exampleCameraInput"),preview=form.querySelector("#examplePreview"),previewImg=form.querySelector("#examplePreviewImg");
  let pendingFile=null;
  const takeFile=file=>{if(!file||!(file.type.startsWith("image/")||/\.(jpe?g|png|webp|heic|heif|avif)$/i.test(file.name)))return;pendingFile=file;previewImg.src=URL.createObjectURL(file);preview.classList.remove("hidden");};
  input.addEventListener("change",()=>{takeFile(input.files[0]);input.value="";});
  cameraInput?.addEventListener("change",()=>{takeFile(cameraInput.files[0]);cameraInput.value="";});
  form.addEventListener("submit",event=>{event.preventDefault();saveJerseyExample(form.elements.name.value.trim(),pendingFile);});
  root.querySelectorAll("[data-delete-example]").forEach(button=>button.addEventListener("click",()=>deleteJerseyExample(button.dataset.deleteExample)));
}
async function saveJerseyExample(name,file){
  const errorBox=root.querySelector("#exampleError"),button=root.querySelector("#exampleSave");
  errorBox.classList.add("hidden");
  if(!name){errorBox.textContent="Escribe un nombre o descripción.";errorBox.classList.remove("hidden");return;}
  if(!file){errorBox.textContent="Añade una foto del ejemplo.";errorBox.classList.remove("hidden");return;}
  if(state.jerseyExampleBusy)return;state.jerseyExampleBusy=true;
  button.disabled=true;button.textContent="Guardando…";
  let uploadedPath="";
  try{
    const compressed=await compressImage(file);
    const path=`products/${state.user.uid}/example-${Date.now()}-${crypto.randomUUID()}.webp`;
    const upload=await supabase.storage.from("catalog-media").upload(path,compressed,{cacheControl:"31536000",contentType:"image/webp",upsert:false});
    if(upload.error)throw new Error(upload.error.message||"Supabase ha rechazado la fotografía.");
    uploadedPath=path;
    const publicUrl=supabase.storage.from("catalog-media").getPublicUrl(path).data.publicUrl;
    await setDoc(doc(collection(db,"jerseyExamples")),{name,image:publicUrl,storagePath:path,createdAt:serverTimestamp()});
    showToast("Ejemplo añadido","success");
  }catch(error){
    console.error(error);
    if(uploadedPath)await supabase.storage.from("catalog-media").remove([uploadedPath]).catch(()=>{});
    errorBox.textContent=/row-level|policy/i.test(String(error?.message||""))?"Supabase ha bloqueado la foto. Ejecuta el archivo supabase-storage-policies.sql y vuelve a iniciar sesión.":firestoreAdminMessage(error,"No se ha podido guardar el ejemplo.");
    errorBox.classList.remove("hidden");
  }finally{
    state.jerseyExampleBusy=false;button.disabled=false;button.textContent="Guardar ejemplo";
  }
}
function deleteJerseyExample(id){
  const example=state.jerseyExamples.find(item=>item.id===id);if(!example)return;
  document.body.insertAdjacentHTML("beforeend",`<div class="admin-dialog-backdrop" id="deleteExampleDialog"><section class="admin-dialog" role="dialog" aria-modal="true"><span>⌫</span><h2>¿Eliminar este ejemplo?</h2><p>Dejará de verse en la página de Fútbol. Esta acción no se puede deshacer.</p><div class="dialog-product"><img src="${esc(example.image)}" alt=""><b>${esc(example.name||"Ejemplo")}</b></div><div class="dialog-actions"><button data-dialog-cancel type="button">Cancelar</button><button class="danger" data-dialog-confirm type="button">Eliminar</button></div></section></div>`);
  const dialog=document.querySelector("#deleteExampleDialog");
  dialog.querySelector("[data-dialog-cancel]").addEventListener("click",()=>dialog.remove());
  dialog.querySelector("[data-dialog-confirm]").addEventListener("click",async()=>{
    const button=dialog.querySelector("[data-dialog-confirm]");button.disabled=true;button.textContent="Eliminando…";
    try{
      await deleteDoc(doc(db,"jerseyExamples",id));
      if(example.storagePath)await supabase.storage.from("catalog-media").remove([example.storagePath]).catch(()=>{});
      dialog.remove();showToast("Ejemplo eliminado","success");
    }catch(error){console.error(error);button.disabled=false;button.textContent="Eliminar";showToast(firestoreAdminMessage(error,"No se ha podido eliminar el ejemplo."),"error");}
  });
}
function requestDate(value){const date=value?.toDate?value.toDate():value?.seconds?new Date(value.seconds*1000):null;return date&&!Number.isNaN(date.getTime())?new Intl.DateTimeFormat("es-ES",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"}).format(date):"Ahora";}
function requestStatusLabel(status){return status==="offered"?"Oferta enviada":status==="closed"?"Cerrada":"Pendiente";}
function customerDisplayName(request){const name=request.customerName||"";if(name&&name!=="Cliente")return name;const email=request.customerEmail||"";return email?email.split("@")[0]:"Cliente";}
function filteredRequests(){const term=norm(state.requestSearch);return state.requests.filter(request=>{const haystack=norm([request.requestNumber,request.clientNumber,request.customerName,request.customerEmail,request.customerPhone,...(request.items||[]).flatMap(item=>[item.name,item.brand,item.size])].join(" "));return(!term||haystack.includes(term))&&(state.requestStatus==="all"||request.status===state.requestStatus);});}
function renderRequests(){const requests=filteredRequests(),pending=state.requests.filter(request=>request.status==="pending").length;root.innerHTML=`<div class="admin-main-shell requests-shell"><header class="admin-page-head"><div><p class="kicker">ATENCIÓN AL CLIENTE</p><h1>Solicitudes</h1><span>Carritos enviados por clientes para preparar una oferta.</span></div><div class="request-summary"><b>${pending}</b><span>pendiente${pending===1?"":"s"}</span></div></header><div class="request-toolbar"><label class="admin-search"><span>⌕</span><input id="requestSearch" type="search" value="${esc(state.requestSearch)}" placeholder="Buscar cliente, número o artículo"></label><select id="requestStatus"><option value="all">Todos los estados</option><option value="pending" ${state.requestStatus==="pending"?"selected":""}>Pendientes</option><option value="offered" ${state.requestStatus==="offered"?"selected":""}>Oferta enviada</option><option value="closed" ${state.requestStatus==="closed"?"selected":""}>Cerradas</option></select></div>${requests.length?`<div class="request-list">${requests.map(requestCard).join("")}</div>`:`<div class="admin-empty"><span>◇</span><h2>No hay solicitudes</h2><p>${state.requests.length?"Cambia la búsqueda o el estado seleccionado.":"Cuando un cliente envíe su carrito aparecerá aquí."}</p></div>`}</div>`;root.querySelector("#requestSearch")?.addEventListener("input",event=>{state.requestSearch=event.target.value;clearTimeout(renderRequests.timer);renderRequests.timer=setTimeout(()=>{renderRequests();const input=root.querySelector("#requestSearch");input?.focus();input?.setSelectionRange(input.value.length,input.value.length);},140);});root.querySelector("#requestStatus")?.addEventListener("change",event=>{state.requestStatus=event.target.value;renderRequests();});root.querySelectorAll("[data-request-offer]").forEach(button=>button.addEventListener("click",()=>openOffer(button.dataset.requestOffer)));root.querySelectorAll("[data-request-close]").forEach(button=>button.addEventListener("click",()=>setRequestStatus(button.dataset.requestClose,"closed")));root.querySelectorAll("[data-request-delete]").forEach(button=>button.addEventListener("click",()=>confirmDeleteRequest(button.dataset.requestDelete)));}
function requestCard(request){const items=Array.isArray(request.items)?request.items:[];return `<article class="request-card"><header><div><span class="request-status ${esc(request.status||"pending")}">${esc(requestStatusLabel(request.status))}</span><b>${esc(request.requestNumber||request.id)}</b><small>${esc(requestDate(request.createdAt))}</small></div><div class="request-customer"><strong>${esc(customerDisplayName(request))}</strong><span>${esc(request.clientNumber||"Sin número")}</span><a href="tel:${esc(request.customerPhone||"")}">${esc(request.customerPhone||"Sin teléfono")}</a></div></header><div class="request-products">${items.map(item=>`<div><img src="${esc(item.image||"producto-1.jpg")}" alt=""><span><b>${esc(item.name||"Artículo")}</b><small>${esc(item.brand||"GINESCLOSET")}${item.size?` · Talla ${esc(item.size)}`:""}</small></span><strong>${esc(price(item.price))}</strong></div>`).join("")}</div>${request.offerPrice?`<div class="request-last-offer"><span>Última oferta</span><b>${esc(request.offerPrice)}</b>${request.offerNote?`<small>${esc(request.offerNote)}</small>`:""}</div>`:""}<footer><span>${items.length} artículo${items.length===1?"":"s"}</span><div><button class="button button-danger-outline" data-request-delete="${esc(request.id)}" type="button">Eliminar</button><button class="button button-secondary" data-request-close="${esc(request.id)}" type="button" ${request.status==="closed"?"disabled":""}>${request.status==="closed"?"Cerrada":"Marcar cerrada"}</button><button class="button button-primary" data-request-offer="${esc(request.id)}" type="button">Preparar oferta por WhatsApp</button></div></footer></article>`;}
function whatsappNumber(value){let digits=String(value||"").replace(/\D/g,"");if(digits.startsWith("00"))digits=digits.slice(2);if(digits.length===9)digits=`34${digits}`;return digits;}
function openOffer(id){const request=state.requests.find(item=>item.id===id);if(!request)return;const phone=whatsappNumber(request.customerPhone);if(phone.length<10){showToast("El teléfono del cliente no es válido para WhatsApp.","error");return;}const items=Array.isArray(request.items)?request.items:[];document.body.insertAdjacentHTML("beforeend",`<div class="admin-dialog-backdrop" id="offerDialog"><section class="admin-dialog offer-dialog" role="dialog" aria-modal="true"><button class="offer-close" data-dialog-cancel type="button" aria-label="Cerrar">×</button><p class="kicker">OFERTA POR WHATSAPP</p><h2>${esc(customerDisplayName(request))}</h2><div class="offer-client"><span>${esc(request.clientNumber||"")}</span><b>${esc(request.customerPhone||"")}</b></div><div class="offer-products">${items.map(item=>`<div><img src="${esc(item.image||"producto-1.jpg")}" alt=""><span><b>${esc(item.name||"Artículo")}</b><small>${esc(item.brand||"")}${item.size?` · ${esc(item.size)}`:""}</small></span></div>`).join("")}</div><form id="offerForm"><label>Oferta total<input name="price" required maxlength="30" value="${esc(request.offerPrice||"")}" placeholder="Ej. 180 €"></label><label>Mensaje adicional<textarea name="note" maxlength="300" placeholder="Ej. Envío incluido y entrega estimada en 48 horas">${esc(request.offerNote||"")}</textarea></label><p class="admin-error hidden" id="offerError"></p><button class="button button-primary" type="submit">Abrir WhatsApp con la oferta</button></form></section></div>`);const dialog=document.querySelector("#offerDialog");dialog.querySelector("[data-dialog-cancel]").addEventListener("click",()=>dialog.remove());dialog.querySelector("#offerForm").addEventListener("submit",event=>sendWhatsappOffer(event,request,phone,dialog));}
async function sendWhatsappOffer(event,request,phone,dialog){event.preventDefault();const form=event.currentTarget,data=new FormData(form),offerPrice=String(data.get("price")||"").trim(),offerNote=String(data.get("note")||"").trim(),button=form.querySelector('button[type="submit"]'),errorBox=form.querySelector("#offerError");if(!offerPrice){errorBox.textContent="Escribe el importe de la oferta.";errorBox.classList.remove("hidden");return;}const itemLines=(request.items||[]).map((item,index)=>`${index+1}. ${item.name}${item.brand?` · ${item.brand}`:""}${item.size?` · Talla ${item.size}`:""}`).join("\n"),message=`Hola ${customerDisplayName(request)}, soy GinesCloset.\n\nOferta para tu solicitud ${request.requestNumber||request.id} (${request.clientNumber||"cliente"}):\n${itemLines}\n\nOferta total: ${offerPrice}${offerNote?`\n${offerNote}`:""}\n\nSi te interesa, respóndenos por aquí.`;const whatsappWindow=window.open("about:blank","_blank");button.disabled=true;button.textContent="Preparando…";try{await setDoc(doc(db,"requests",request.id),{status:"offered",offerPrice,offerNote,offeredAt:serverTimestamp(),updatedAt:serverTimestamp()},{merge:true});if(whatsappWindow)whatsappWindow.location.href=`https://wa.me/${phone}?text=${encodeURIComponent(message)}`;else location.href=`https://wa.me/${phone}?text=${encodeURIComponent(message)}`;dialog.remove();showToast("Oferta preparada en WhatsApp","success");}catch(error){console.error(error);whatsappWindow?.close();errorBox.textContent=firestoreAdminMessage(error,"No se ha podido guardar la oferta.");errorBox.classList.remove("hidden");button.disabled=false;button.textContent="Abrir WhatsApp con la oferta";}}
async function setRequestStatus(id,status){try{await setDoc(doc(db,"requests",id),{status,updatedAt:serverTimestamp()},{merge:true});showToast("Solicitud actualizada","success");}catch(error){console.error(error);showToast(firestoreAdminMessage(error,"No se ha podido actualizar la solicitud."),"error");}}

function confirmDeleteRequest(id){const request=state.requests.find(item=>item.id===id);if(!request)return;const items=Array.isArray(request.items)?request.items:[];document.body.insertAdjacentHTML("beforeend",`<div class="admin-dialog-backdrop" id="deleteRequestDialog"><section class="admin-dialog" role="dialog" aria-modal="true"><span>⌫</span><h2>¿Eliminar esta solicitud?</h2><p>Se eliminará permanentemente la solicitud <b>${esc(request.requestNumber||request.id)}</b> de <b>${esc(customerDisplayName(request))}</b>. Esta acción no se puede deshacer.</p><div class="dialog-product"><b>${items.map(item=>esc(item.name||"Artículo")).join(", ")||"Sin artículos"}</b></div><div class="dialog-actions"><button data-dialog-cancel type="button">Cancelar</button><button class="danger" data-dialog-delete-request type="button">Eliminar solicitud</button></div></section></div>`);const dialog=document.querySelector("#deleteRequestDialog");dialog.querySelector("[data-dialog-cancel]").addEventListener("click",()=>dialog.remove());dialog.querySelector("[data-dialog-delete-request]").addEventListener("click",()=>deleteRequest(id,dialog));}
async function deleteRequest(id,dialog){const button=dialog.querySelector("[data-dialog-delete-request]");button.disabled=true;button.textContent="Eliminando…";try{await deleteDoc(doc(db,"requests",id));dialog.remove();showToast("Solicitud eliminada","success");}catch(error){console.error(error);button.disabled=false;button.textContent="Eliminar solicitud";showToast(firestoreAdminMessage(error,"No se ha podido eliminar la solicitud."),"error");}}

function emptyEditorModel(){return{id:"",name:"",brand:"",category:"camisetas",price:"Consultar",description:"",badge:"NUEVO",sizes:["S","M","L"],active:false,condition:"Muy buen estado",color:"",material:"",measurements:"",authenticity:"",unique:true,createdOrder:Date.now(),images:[],storagePaths:[],stock:0};}
function editorProduct(){return state.editId?state.products.find(item=>item.id===state.editId):null;}
function prepareMedia(product){state.media=product?productImages(product).map((url,index)=>({id:`existing-${index}`,url,path:product.storagePaths[index]||"",file:null,existing:true})) : [];state.removedPaths=[];}
