function updatePreview(){const product=draftFromForm(),image=state.media[0]?.url;const imageRoot=root.querySelector("#previewImage");if(imageRoot)imageRoot.innerHTML=image?`<img src="${esc(image)}" alt="Vista previa">`:'<span>◇</span>';root.querySelector("#previewMeta").textContent=`${product.brand||"Marca"} · ${product.condition||"Estado"}`;root.querySelector("#previewName").textContent=product.name||"Nombre del artículo";root.querySelector("#previewPrice").textContent=price(product.price);root.querySelector("#previewSizes").innerHTML=`${product.unique?'<b>PIEZA ÚNICA</b>':""}${product.sizes.map(size=>`<i>${esc(size)}</i>`).join("")}`;}

async function addMediaFiles(fileList){
  const files=[...fileList].filter(file=>file.type.startsWith("image/")||/\.(jpe?g|png|webp|heic|heif|avif|gif|bmp)$/i.test(file.name));if(!files.length){showToast("Selecciona o haz una foto.","error");return;}if(state.media.length+files.length>8){showToast("Puedes añadir un máximo de 8 fotografías.","error");return;}
  for(const file of files){try{const compressed=await compressImage(file);state.media.push({id:`new-${crypto.randomUUID()}`,url:URL.createObjectURL(compressed),file:compressed,path:"",existing:false});}catch(error){console.error(error);showToast(`No se pudo preparar ${file.name}.`,"error");}}
  state.dirty=true;renderMedia();updatePreview();
}
async function compressImage(file){
  const bitmap=await createImageBitmap(file),max=1800,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),width=Math.round(bitmap.width*scale),height=Math.round(bitmap.height*scale);const canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;canvas.getContext("2d",{alpha:false}).drawImage(bitmap,0,0,width,height);bitmap.close();const blob=await new Promise((resolve,reject)=>canvas.toBlob(result=>result?resolve(result):reject(new Error("No se pudo comprimir")),"image/webp",.86));return new File([blob],`${file.name.replace(/\.[^.]+$/,"")}.webp`,{type:"image/webp"});
}
function renderMedia(){const grid=root.querySelector("#mediaGrid");if(!grid)return;grid.innerHTML=state.media.map((item,index)=>`<article class="media-item" draggable="true" data-media-index="${index}"><img src="${esc(item.url)}" alt="Fotografía ${index+1}">${index===0?'<span class="cover">PORTADA</span>':""}<div class="media-item-actions"><button data-media-cover="${index}" type="button">Portada</button><button data-media-left="${index}" type="button">←</button><button data-media-right="${index}" type="button">→</button><button class="danger" data-media-remove="${index}" type="button">×</button></div></article>`).join("");
  grid.querySelectorAll("[data-media-cover]").forEach(button=>button.addEventListener("click",()=>moveMedia(Number(button.dataset.mediaCover),0)));grid.querySelectorAll("[data-media-left]").forEach(button=>button.addEventListener("click",()=>moveMedia(Number(button.dataset.mediaLeft),Math.max(0,Number(button.dataset.mediaLeft)-1))));grid.querySelectorAll("[data-media-right]").forEach(button=>button.addEventListener("click",()=>moveMedia(Number(button.dataset.mediaRight),Math.min(state.media.length-1,Number(button.dataset.mediaRight)+1))));grid.querySelectorAll("[data-media-remove]").forEach(button=>button.addEventListener("click",()=>removeMedia(Number(button.dataset.mediaRemove))));
  let dragged=-1;grid.querySelectorAll("[data-media-index]").forEach(item=>{item.addEventListener("dragstart",()=>dragged=Number(item.dataset.mediaIndex));item.addEventListener("dragover",event=>event.preventDefault());item.addEventListener("drop",event=>{event.preventDefault();moveMedia(dragged,Number(item.dataset.mediaIndex));});});
}
function moveMedia(from,to){if(from<0||to<0||from===to)return;const[item]=state.media.splice(from,1);state.media.splice(to,0,item);state.dirty=true;renderMedia();updatePreview();}
function removeMedia(index){const[item]=state.media.splice(index,1);if(item?.existing&&item.path)state.removedPaths.push(item.path);if(item&&!item.existing)URL.revokeObjectURL(item.url);state.dirty=true;renderMedia();updatePreview();}

async function uploadMedia(item,index,total){if(item.existing)return item;const extension="webp",path=`products/${state.user.uid}/${Date.now()}-${crypto.randomUUID()}.${extension}`;updateProgress(index,total);const result=await supabase.storage.from("catalog-media").upload(path,item.file,{cacheControl:"31536000",contentType:item.file.type,upsert:false});if(result.error)throw new Error(result.error.message||"Supabase ha rechazado la fotografía.");const publicUrl=supabase.storage.from("catalog-media").getPublicUrl(path).data.publicUrl;return{...item,url:publicUrl,path,existing:true,file:null};}
function updateProgress(done,total){const box=root.querySelector("#uploadProgress"),bar=box?.querySelector("i");box?.classList.remove("hidden");if(bar)bar.style.width=`${Math.round(done/Math.max(1,total)*100)}%`;}
function storageErrorMessage(error){
  const message=String(error?.message||"").toLowerCase();
  if(message.includes("row-level")||message.includes("policy"))return"Supabase ha bloqueado la fotografía. En Supabase abre SQL Editor, ejecuta completo el archivo supabase-storage-policies.sql y vuelve a iniciar sesión.";
  if(message.includes("jwt")||message.includes("unauthorized")||message.includes("authorization"))return"Supabase no reconoce la sesión de Firebase. Activa Authentication > Third-Party Auth > Firebase con el proyecto ginescloset-12beb y vuelve a iniciar sesión.";
  return`No se ha podido subir la fotografía: ${error?.message||"error desconocido"}`;
}
async function saveProduct(mode){
  const form=root.querySelector("#productForm"),errorBox=root.querySelector("#editorError"),buttons=[...form.querySelectorAll("[data-save]")];errorBox.classList.add("hidden");const product=draftFromForm();if(mode==="publish")product.active=true;
  if(mode==="draft")product.active=false;
  if(!product.name){showEditorError("Escribe el nombre del artículo.");return;}if(!BRANDS.includes(product.brand)){showEditorError("Selecciona una marca de la lista.");return;}if(!CATEGORIES.some(item=>item[0]===product.category)){showEditorError("Selecciona una categoría.");return;}if(!validProductPrice(product.price)){showEditorError("Escribe un precio válido o utiliza “Consultar”.");return;}if(!product.sizes.length){showEditorError("Selecciona al menos una talla.");return;}if(!state.media.length){showEditorError("Añade al menos una fotografía.");return;}
  buttons.forEach(button=>button.disabled=true);const pressed=form.querySelector(`[data-save="${mode}"]`);if(pressed)pressed.textContent="Guardando…";
  const uploadedPaths=[];let stage="upload";
  try{
    const total=state.media.filter(item=>!item.existing).length;let count=0;const preparedMedia=[];for(const item of state.media){const prepared=item.existing?item:await uploadMedia(item,++count,total);preparedMedia.push(prepared);if(!item.existing)uploadedPaths.push(prepared.path);}
    updateProgress(total||1,total||1);stage="catalog";const reference=state.editId?doc(db,"products",state.editId):doc(collection(db,"products"));const images=preparedMedia.map(item=>item.url),storagePaths=preparedMedia.map(item=>item.path||"");await setDoc(reference,{...product,images,storagePaths,image:images[0],storagePath:storagePaths[0]||"",updatedAt:serverTimestamp(),createdAt:state.editId?(editorProduct()?.createdAt||serverTimestamp()):serverTimestamp()},{merge:Boolean(state.editId)});
    state.media.filter(item=>!item.existing).forEach(item=>URL.revokeObjectURL(item.url));state.media=preparedMedia;
    if(state.removedPaths.length){const removed=await supabase.storage.from("catalog-media").remove(state.removedPaths);if(removed.error)console.warn("No se pudieron limpiar algunas fotografías antiguas",removed.error);}
    localStorage.removeItem("gc_admin_draft");state.dirty=false;showToast(product.active?"Artículo publicado correctamente":"Borrador guardado","success");state.view="catalog";state.editId="";setActiveNav("catalog");renderCatalog();
  }catch(error){console.error(error);if(uploadedPaths.length)await supabase.storage.from("catalog-media").remove(uploadedPaths);showEditorError(stage==="upload"?storageErrorMessage(error):firestoreAdminMessage(error,"La fotografía se preparó, pero Firebase no pudo guardar el artículo."));buttons.forEach(button=>button.disabled=false);if(pressed)pressed.textContent=mode==="draft"?"Guardar borrador":"Publicar artículo";}
}
