function confirmDelete(id){const product=state.products.find(item=>item.id===id);if(!product)return;document.body.insertAdjacentHTML("beforeend",`<div class="admin-dialog-backdrop" id="deleteDialog"><section class="admin-dialog" role="dialog" aria-modal="true"><span>⌫</span><h2>¿Eliminar este artículo?</h2><p>Esta acción eliminará el artículo del catálogo. Sus fotografías de Supabase también se eliminarán.</p><div class="dialog-product"><img src="${esc(product.image)}" alt=""><b>${esc(product.name)}</b></div><div class="dialog-actions"><button data-dialog-cancel type="button">Cancelar</button><button class="danger" data-dialog-delete type="button">Eliminar definitivamente</button></div></section></div>`);const dialog=document.querySelector("#deleteDialog");dialog.querySelector("[data-dialog-cancel]").addEventListener("click",()=>dialog.remove());dialog.querySelector("[data-dialog-delete]").addEventListener("click",()=>deleteProduct(product,dialog));}
